fn test_vmm_page_fault() {
    let start_addr: usize = 0x1_0000;
    let p4 = PageTableAllocator::<MockKernel>::allocate_frame(true).unwrap();
    let platform = MockKernel::new(p4.start_address());
    let litebox = LiteBox::new(platform);
    let vmm = PageManager::<_, PAGE_SIZE>::new(&litebox);
    unsafe {
        assert_eq!(
            vmm.create_writable_pages(
                Some(NonZeroAddress::new(start_addr).unwrap()),
                NonZeroPageSize::new(4 * PAGE_SIZE).unwrap(),
                CreatePagesFlags::FIXED_ADDR,
                |_: UserMutPtr<u8>| Ok(0),
            )
            .unwrap()
            .as_usize(),
            start_addr
        );
    }
    // [0x1_0000, 0x1_4000)

    // Access page w/o mapping
    assert!(matches!(
        unsafe {
            vmm.handle_page_fault(
                start_addr + 6 * PAGE_SIZE,
                PageFaultErrorCode::USER_MODE.bits(),
            )
        },
        Err(PageFaultError::AccessError(_))
    ));

    // Access non-present page w/ mapping
    assert!(
        unsafe {
            vmm.handle_page_fault(
                start_addr + 2 * PAGE_SIZE,
                PageFaultErrorCode::USER_MODE.bits(),
            )
        }
        .is_ok()
    );

    // insert stack mapping
    let stack_addr: usize = 0x1000_0000;
    unsafe {
        assert_eq!(
            vmm.create_stack_pages(
                Some(NonZeroAddress::new(stack_addr).unwrap()),
                NonZeroPageSize::new(4 * PAGE_SIZE).unwrap(),
                CreatePagesFlags::FIXED_ADDR,
            )
            .unwrap()
            .as_usize(),
            stack_addr
        );
    }
    // [0x1_0000, 0x1_4000), [0x1000_0000, 0x1000_4000)
    // Test stack growth
    assert!(
        unsafe {
            vmm.handle_page_fault(stack_addr - PAGE_SIZE, PageFaultErrorCode::USER_MODE.bits())
        }
        .is_ok()
    );
    assert_eq!(
        vmm.mappings()
            .iter()
            .map(|v| v.0.clone())
            .collect::<Vec<_>>(),
        vec![0x1_0000..0x1_4000, 0x0fff_f000..0x1000_4000]
    );
    // Cannot grow stack too far
    assert!(matches!(
        unsafe {
            vmm.handle_page_fault(
                start_addr + 100 * PAGE_SIZE,
                PageFaultErrorCode::USER_MODE.bits(),
            )
        },
        Err(PageFaultError::AllocationFailed)
    ));
}

litebox_common_linux/src/mm.rs:257:304 sys_madvise
pub fn sys_madvise<
    Platform: litebox::platform::RawPointerProvider
        + litebox::sync::RawSyncPrimitivesProvider
        + litebox::platform::PageManagementProvider<{ litebox::mm::linux::PAGE_SIZE }>,
>(
    pm: &litebox::mm::PageManager<Platform, { litebox::mm::linux::PAGE_SIZE }>,
    addr: UserPtrMut<u8>,
    len: usize,
    advice: crate::MadviseBehavior,
) -> Result<(), Errno> {
    if addr.as_usize() & !PAGE_MASK != 0 {
        return Err(Errno::EINVAL);
    }
    if len == 0 {
        return Ok(());
    }
    let aligned_len = len.next_multiple_of(PAGE_SIZE);
    if aligned_len == 0 {
        // overflow
        return Err(Errno::EINVAL);
    }
    let Some(_end) = addr.as_usize().checked_add(aligned_len) else {
        return Err(Errno::EINVAL);
    };

    let addr = addr.to_platform_ptr::<Platform>();
    match advice {
        crate::MadviseBehavior::Normal
        | crate::MadviseBehavior::DontFork
        | crate::MadviseBehavior::DoFork => {
            // No-op for now, as we don't support fork yet.
            Ok(())
        }
        crate::MadviseBehavior::DontNeed => {
            // After a successful MADV_DONTNEED operation, the semantics of memory access in the specified region are changed:
            // subsequent accesses of pages in the range will succeed, but will result in either repopulating the memory contents
            // from the up-to-date contents of the underlying mapped file (for shared file mappings, shared anonymous mappings,
            // and shmem-based techniques such as System V shared memory segments) or zero-fill-on-demand pages for anonymous private mappings.
            //
            // Note we do not support shared memory yet, so this is just to discard the pages without removing the mapping.
            unsafe { pm.reset_pages(addr, aligned_len, false) }.map_err(Errno::from)
        }
        crate::MadviseBehavior::Free => {
            unsafe { pm.reset_pages(addr, aligned_len, true) }.map_err(Errno::from)
        }
        _ => unimplemented!("Unsupported madvise behavior {:?}", advice),
    }
}

