    fn test_guard_page_gap() {
        let allocator = VmapRegionAllocator::new();

        let va_a = allocator.allocate_va(1).unwrap();
        let va_b = allocator.allocate_va(1).unwrap();

        // Allocations should be separated by at least GUARD_PAGES unmapped pages
        let gap_pages = (va_b.as_u64() - va_a.as_u64()) / PAGE_SIZE as u64;
        assert!(
            gap_pages >= (1 + GUARD_PAGES as u64),
            "expected at least {} pages between allocations, got {}",
            1 + GUARD_PAGES,
            gap_pages
        );
    }

litebox_shim_optee/src/loader/ta_stack.rs:292:314 allocate_stack
pub(crate) fn allocate_stack(task: &crate::Task, stack_base: Option<usize>) -> Option<TaStack> {
    let sp = if let Some(stack_base) = stack_base {
        UserMutPtr::from_usize(stack_base)
    } else {
        let length = litebox::mm::linux::NonZeroPageSize::new(super::DEFAULT_STACK_SIZE)
            .expect("DEFAULT_STACK_SIZE is not page-aligned");
        unsafe {
            task.global
                .pm
                .create_stack_pages(
                    None,
                    length,
                    // Pre-populate: stack initialization runs before run_thread_arch
                    // sets up the kernel-mode demand paging infrastructure.
                    CreatePagesFlags::POPULATE_PAGES_IMMEDIATELY,
                )
                .ok()?
        }
    };
    let stack = TaStack::new(sp, super::DEFAULT_STACK_SIZE)?;

    Some(stack)
}

